  "开放工位": { "zh-Hant": "開放工位", ja: "オープンワークステーション", en: "Open workstations", ko: "오픈 워크스테이션" },
  "开放时段": { "zh-Hant": "開放時段", ja: "営業時間", en: "Open slot Hours", ko: "영업시간" },
  "开放预约": { "zh-Hant": "開放預約", ja: "予約受付中", en: "Open for reservations", ko: "예약 접수 중" },
