export function getTranslationLookupCandidates(language: Language): TargetLanguage[] {
  if (language === "zh") {
    return [];
  }

  return translationLookupOrder[language];
}

function resolveTranslationEntry(entry: TranslationEntry | undefined, language: Language) {
  if (!entry || language === "zh") {
    return null;
  }

  for (const candidate of getTranslationLookupCandidates(language)) {
    const value = normalizeTranslationValue(entry[candidate]);

    if (value) {
      return value;
    }
  }

  return null;
}

const normalizedTranslationValueCache = new Map<string, string | null>();

function normalizeTranslationValue(value: string | undefined) {
  if (!value) {
    return null;
  }

  if (normalizedTranslationValueCache.has(value)) {
    return normalizedTranslationValueCache.get(value) ?? null;
  }

  const trimmed = value.trim();
  const extracted = extractIfErrorFallback(trimmed);
  const normalized = (extracted ?? trimmed).trim();
  const result =
    normalized &&
    !isSpreadsheetErrorValue(normalized) &&
    !looksLikeSpreadsheetFormula(normalized) &&
    !normalized.includes("__xludf.DUMMYFUNCTION")
      ? normalized
      : null;

  normalizedTranslationValueCache.set(value, result);

  return result;
}

function looksLikeSpreadsheetFormula(value: string) {
  return value.trim().startsWith("=");
}

function extractIfErrorFallback(value: string) {
  const prefix = "=IFERROR(";

  if (!value.startsWith(prefix) || !value.endsWith(")")) {
    return null;
  }

  const inner = value.slice(prefix.length, -1);
  const commaIndex = findTopLevelComma(inner);

  if (commaIndex < 0) {
    return null;
  }

  const fallbackExpression = inner.slice(commaIndex + 1).trim();
  const literals = extractSpreadsheetStringLiterals(fallbackExpression);

  return literals.length > 0 ? literals.join("") : null;
}

function findTopLevelComma(value: string) {
  let depth = 0;
  let inString = false;

  for (let index = 0; index < value.length; index += 1) {
    const character = value[index];

    if (inString) {
      if (character === '"') {
        if (value[index + 1] === '"') {
          index += 1;
        } else {
          inString = false;
        }
      }

      continue;
    }

    if (character === '"') {
      inString = true;
      continue;
    }

    if (character === "(") {
      depth += 1;
      continue;
    }

    if (character === ")") {
      depth = Math.max(0, depth - 1);
      continue;
    }

    if (character === "," && depth === 0) {
      return index;
    }
  }

  return -1;
}

function extractSpreadsheetStringLiterals(value: string) {
  const literals: string[] = [];

  for (let index = 0; index < value.length; index += 1) {
    if (value[index] !== '"') {
      continue;
    }

    let literal = "";
    index += 1;

    while (index < value.length) {
      const character = value[index];

      if (character === '"') {
        if (value[index + 1] === '"') {
          literal += '"';
          index += 2;
          continue;
        }

        break;
      }

      literal += character;
      index += 1;
    }

    literals.push(literal);
  }

  return literals;
}

function isSpreadsheetErrorValue(value: string) {
  const normalized = value.trim().toUpperCase();

  return (
    normalized === "#NAME?" ||
    normalized === "#VALUE!" ||
    normalized === "#REF!" ||
    normalized === "#DIV/0!" ||
    normalized === "#N/A" ||
    normalized === "#NUM!" ||
    normalized === "#NULL!" ||
    normalized === "#SPILL!" ||
    normalized === "#CALC!"
  );
}

function translateDynamicReviewCount(core: string, language: Language): string | null {
  const match = core.match(/^(.*?)(\d+)人评价$/);

  if (!match) {
    return null;
  }

  const [, prefix, count] = match;
  const translatedPrefix: string = prefix.trim() ? translateText(prefix.trim(), language) : "";
  const prefixWithSpace: string = translatedPrefix ? `${translatedPrefix} ` : "";

  if (language === "zh-Hant") {
    return `${prefixWithSpace}${count}人評價`;
  }

  if (language === "ja") {
    return `${prefixWithSpace}${count}人の評価`;
  }

  if (language === "en") {
    return `${prefixWithSpace}${count} reviews`;
  }

  if (language === "ko") {
    return `${prefixWithSpace}${count}명 평가`;
  }

  return null;
}

function translateDisappearingCountdownDuration(duration: string, language: Language) {
  if (language !== "ja") {
    return translateText(duration, language);
  }

  return duration
    .replace(/(\d[\d,]*)\s*分钟/gu, "$1分")
    .replace(/(\d[\d,]*)\s*小时/gu, "$1時間")
    .replace(/(\d[\d,]*)\s*日/gu, "$1日")
    .replace(/(\d[\d,]*)\s*月/gu, "$1か月");
}

function translateGroupPrivacyCountdownStatus(core: string, language: Language): string | null {
  const match = core.match(/^(.+)后对话消失 · (按发送时间开始倒计时|全员看过后开始倒计时)$/u);

  if (!match || language !== "ja") {
    return null;
  }

  const [, durationSource, startModeSource] = match;
  const duration = translateDisappearingCountdownDuration(durationSource, language);

  return startModeSource === "全员看过后开始倒计时"
    ? `全員既読後の${duration}後に会話が消えます`
    : `送信後の${duration}後に会話が消えます`;
}

const englishMonthNames = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December"
];

function translateDynamicDateLabel(core: string, language: Language): string | null {
  const fullDateMatch = core.match(/^(\d{4})年(\d{1,2})月(\d{1,2})日(?:\s+(\d{1,2}:\d{2}))?$/);
  const shortDateMatch = core.match(/^(\d{1,2})月(\d{1,2})日(?:\s+(\d{1,2}:\d{2}))?$/);

  if (!fullDateMatch && !shortDateMatch) {
    return null;
  }

  const [, yearOrMonth, monthOrDay, dayOrTime, fullTime] = fullDateMatch ?? [];
  const [, shortMonth, shortDay, shortTime] = shortDateMatch ?? [];
  const year = fullDateMatch ? yearOrMonth : "";
  const month = Number(fullDateMatch ? monthOrDay : shortMonth);
  const day = Number(fullDateMatch ? dayOrTime : shortDay);
  const time = fullDateMatch ? fullTime : shortTime;

  if (!Number.isFinite(month) || !Number.isFinite(day)) {
    return null;
  }

  const timeSuffix = time ? ` ${time}` : "";

  if (language === "en") {
    const monthName = englishMonthNames[Math.max(0, Math.min(11, month - 1))] ?? String(month);
    return year ? `${monthName} ${day}, ${year}${timeSuffix}` : `${monthName} ${day}${timeSuffix}`;
  }

  if (language === "ko") {
    return year ? `${year}년 ${month}월 ${day}일${timeSuffix}` : `${month}월 ${day}일${timeSuffix}`;
  }

  if (language === "ja") {
    return year ? `${year}年${month}月${day}日${timeSuffix}` : `${month}月${day}日${timeSuffix}`;
  }

  if (language === "zh-Hant") {
    return year ? `${year}年${month}月${day}日${timeSuffix}` : `${month}月${day}日${timeSuffix}`;
  }

  return null;
}

function translateDynamicCountLabel(core: string, language: Language): string | null {
  const match = core.match(/^(\d[\d,]*)(?:\/(\d[\d,]*))?\s*(天|单|件|人|格|个|条|张|家|套|项|类|笔|次|位|名)$/);

  if (!match) {
    return null;
  }

  const [, current, total, unit] = match;
  const value = total ? `${current}/${total}` : current;

  if (language === "zh-Hant") {
    const unitMap: Record<string, string> = {
      天: "天",
      单: "單",
      件: "件",
      人: "人",
      格: "格",
      个: "個",
      条: "條",
      张: "張",
      家: "家",
      套: "套",
      项: "項",
      类: "類",
      笔: "筆",
      次: "次",
      位: "位",
      名: "名"
    };

    return `${value} ${unitMap[unit] ?? unit}`;
  }

  if (language === "ja") {
    const unitMap: Record<string, string> = {
      天: "日",
      单: "件",
      件: "件",
      人: "人",
      格: "枠",
      个: "件",
      条: "件",
      张: "件",
      家: "店舗",
      套: "件",
      项: "件",
      类: "カテゴリ",
      笔: "件",
      次: "回",
      位: "人",
      名: "人"
    };

    return `${value}${unitMap[unit] ?? unit}`;
  }

  if (language === "en") {
    const unitMap: Record<string, string> = {
      天: "days",
      单: "orders",
      件: "items",
      人: "people",
      格: "slots",
      个: "items",
      条: "items",
      张: "records",
      家: "shops",
      套: "sets",
      项: "items",
      类: "categories",
      笔: "records",
      次: "times",
      位: "people",
      名: "people"
    };

    return `${value} ${unitMap[unit] ?? unit}`;
  }

  if (language === "ko") {
    const unitMap: Record<string, string> = {
      天: "일",
      单: "건",
      件: "건",
      人: "명",
      格: "칸",
      个: "개",
      条: "건",
      张: "건",
      家: "개 매장",
      套: "세트",
      项: "개",
      类: "개 카테고리",
      笔: "건",
      次: "회",
      位: "명",
      名: "명"
    };

    return `${value}${unitMap[unit] ?? unit}`;
  }

  return null;
}

function translateDynamicPackageLabel(core: string, language: Language): string | null {
  const match = core.match(/^(.*?)\s*(\d+)\s*号套餐$/);

  if (!match) {
    return null;
  }

  const [, prefix, packageNumber] = match;
  const translatedPrefix = prefix.trim() ? translateText(prefix.trim(), language) : "";

  if (language === "zh-Hant") {
    return `${translatedPrefix} ${packageNumber} 號套餐`.trim();
  }

  if (language === "ja") {
    return `${translatedPrefix} ${packageNumber}番パッケージ`.trim();
  }

  if (language === "en") {
    return `${translatedPrefix} package ${packageNumber}`.trim();
  }

  if (language === "ko") {
    return `${translatedPrefix} ${packageNumber}번 패키지`.trim();
  }

  return null;
}

function translateDynamicDispatchOverlapLabel(core: string, language: Language): string | null {
  const match = core.match(/^(.*?)\s*与当前已排时段重叠，需要立即改派或改时。$/);

  if (!match) {
    return null;
  }

  const [, serviceName] = match;
  const translatedServiceName = serviceName.trim() ? translateText(serviceName.trim(), language) : "";

  if (language === "zh-Hant") {
    return `${translatedServiceName} 與目前已排時段重疊，需要立即改派或改時。`.trim();
  }

  if (language === "ja") {
    return `${translatedServiceName} は割当済み時間帯と重複しています。すぐに再割当または時間変更が必要です。`.trim();
  }

  if (language === "en") {
    return `${translatedServiceName} overlaps with the currently scheduled time slot and needs reassignment or rescheduling immediately.`.trim();
  }

  if (language === "ko") {
    return `${translatedServiceName}이(가) 현재 배정된 시간대와 겹치므로 즉시 재배정하거나 시간을 변경해야 합니다.`.trim();
  }

  return null;
}

