function cleanupRuntimeTranslation(value: string, language: Language) {
  if (language === "zh") {
    return value;
  }

  const runtimeCleaned = (runtimeTranslationCleanup[language] ?? []).reduce((current, [pattern, replacement]) => current.replace(pattern, replacement), value);

  return (manualI18nCorrectionLocks[language] ?? []).reduce((current, [pattern, replacement]) => current.replace(pattern, replacement), runtimeCleaned);
}

function applyManualContextCorrection(source: string, translated: string, language: Language, context: TranslationContext = {}) {
  if (language === "zh") {
    return translated;
  }

  const core = source.trim();
  const portal = context.portal ?? "user";
  const lock = (manualI18nContextCorrectionLocks[language] ?? []).find((item) => {
    const sourceMatches = item.sources.includes(core);
    const portalMatches = !item.portals || item.portals.includes(portal);

    return sourceMatches && portalMatches;
  });

  return lock?.replacement ?? translated;
}

export function translateText(source: string, language: Language): string {
  const leading = source.match(/^\s*/)?.[0] ?? "";
  const trailing = source.match(/\s*$/)?.[0] ?? "";
  const core = source.trim();

  if (!core) {
    return source;
  }

  const sourceOverride = coreReadApiSourceTranslationOverrides[core]?.[language];

  if (sourceOverride) {
    return `${leading}${cleanupRuntimeTranslation(sourceOverride, language)}${trailing}`;
  }

  if (language === "zh") {
    return source;
  }

  const exact = resolveTranslationEntry(translations[core], language);

  if (exact) {
    return `${leading}${cleanupRuntimeTranslation(exact, language)}${trailing}`;
  }

  const dynamicDateLabel: string | null = translateDynamicDateLabel(core, language);

  if (dynamicDateLabel) {
    return `${leading}${cleanupRuntimeTranslation(dynamicDateLabel, language)}${trailing}`;
  }

  const dynamicCountLabel: string | null = translateDynamicCountLabel(core, language);

  if (dynamicCountLabel) {
    return `${leading}${cleanupRuntimeTranslation(dynamicCountLabel, language)}${trailing}`;
  }

  const dynamicPackageLabel: string | null = translateDynamicPackageLabel(core, language);

  if (dynamicPackageLabel) {
    return `${leading}${cleanupRuntimeTranslation(dynamicPackageLabel, language)}${trailing}`;
  }

  const dynamicDispatchOverlapLabel: string | null = translateDynamicDispatchOverlapLabel(core, language);

  if (dynamicDispatchOverlapLabel) {
    return `${leading}${cleanupRuntimeTranslation(dynamicDispatchOverlapLabel, language)}${trailing}`;
  }

  const dynamicReviewCount: string | null = translateDynamicReviewCount(core, language);

  if (dynamicReviewCount) {
    return `${leading}${cleanupRuntimeTranslation(dynamicReviewCount, language)}${trailing}`;
  }

  const dynamicGroupPrivacyCountdownStatus: string | null = translateGroupPrivacyCountdownStatus(core, language);

  if (dynamicGroupPrivacyCountdownStatus) {
    return `${leading}${cleanupRuntimeTranslation(dynamicGroupPrivacyCountdownStatus, language)}${trailing}`;
  }

  const translated = Object.entries(translations)
    .filter(([phrase]) => phrase.length >= 2 && core.includes(phrase))
    .sort(([a], [b]) => b.length - a.length)
    .reduce((text, [phrase, values]) => {
      const replacement = resolveTranslationEntry(values, language);

      return replacement ? text.split(phrase).join(replacement) : text;
    }, core);

  return `${leading}${cleanupRuntimeTranslation(translated, language)}${trailing}`;
}

export function translateTextForContext(source: string, language: Language, context: TranslationContext = {}): string {
  return applyManualContextCorrection(source, translateText(source, language), language, context);
}
